void commit_active_terrain_stroke(EditorState &state);

void enqueue_mcp_click(EditorState &state, float x, float y, int button,
                       int hold_frames = 1) {
  EditorState::InputEvent move;
  move.kind = EditorState::InputEvent::Kind::Move;
  move.x = x;
  move.y = y;
  state.mcp_input_queue.push_back(move);
  EditorState::InputEvent down;
  down.kind = EditorState::InputEvent::Kind::Button;
  down.button = button;
  down.down = true;
  state.mcp_input_queue.push_back(down);
  EditorState::InputEvent wait;
  wait.kind = EditorState::InputEvent::Kind::Wait;
  wait.wait_frames = (std::max)(1, hold_frames);
  state.mcp_input_queue.push_back(wait);
  EditorState::InputEvent up;
  up.kind = EditorState::InputEvent::Kind::Button;
  up.button = button;
  up.down = false;
  state.mcp_input_queue.push_back(up);
}

bool resolve_mcp_client_xy(SDL_Window *window, const nlohmann::json &params,
                           float &out_x, float &out_y, std::string *error,
                           const EditorUiHotspotRegistry *hotspots = nullptr) {
  if (params.contains("targetId") && params["targetId"].is_string()) {
    const auto target_id = params["targetId"].get<std::string>();
    if (!hotspots) {
      if (error)
        *error = "targetId requires live hotspot registry";
      return false;
    }
    const auto *spot = hotspots->find_exact(target_id);
    if (!spot) {
      if (error)
        *error = "Unknown targetId: " + target_id;
      return false;
    }
    out_x = spot->cx;
    out_y = spot->cy;
    return true;
  }
  int w = 1, h = 1;
  SDL_GetWindowSize(window, &w, &h);
  if (params.contains("nx") || params.contains("ny")) {
    const float nx = params.value("nx", 0.5f);
    const float ny = params.value("ny", 0.5f);
    out_x = nx * static_cast<float>(w);
    out_y = ny * static_cast<float>(h);
    return true;
  }
  if (params.contains("x") || params.contains("y")) {
    out_x = params.value("x", 0.0f);
    out_y = params.value("y", 0.0f);
    return true;
  }
  if (error)
    *error = "Provide x/y client pixels or nx/ny normalized [0,1]";
  return false;
}

void drain_mcp_input_queue(EditorState &state, SDL_Window *window) {
  if (state.mcp_input_queue.empty()) {
    state.mcp_draw_cursor =
        state.mcp_cursor_x >= 0.0f && state.mcp_cursor_y >= 0.0f;
    return;
  }
  auto &io = ImGui::GetIO();
  while (!state.mcp_input_queue.empty()) {
    auto &ev = state.mcp_input_queue.front();
    if (ev.kind == EditorState::InputEvent::Kind::Wait) {
      if (ev.wait_frames > 1) {
        --ev.wait_frames;
        break;
      }
      state.mcp_input_queue.pop_front();
      continue;
    }
    if (ev.kind == EditorState::InputEvent::Kind::Move) {
      state.mcp_cursor_x = ev.x;
      state.mcp_cursor_y = ev.y;
      state.mcp_draw_cursor = true;
      SDL_WarpMouseInWindow(window, static_cast<float>(ev.x),
                            static_cast<float>(ev.y));
      io.AddMousePosEvent(ev.x, ev.y);
    } else if (ev.kind == EditorState::InputEvent::Kind::Look) {
      state.mcp_look_dx += ev.x;
      state.mcp_look_dy += ev.y;
    } else if (ev.kind == EditorState::InputEvent::Kind::Button) {
      if (state.mcp_cursor_x >= 0.0f)
        io.AddMousePosEvent(state.mcp_cursor_x, state.mcp_cursor_y);
      io.AddMouseButtonEvent(ev.button, ev.down);
    } else if (ev.kind == EditorState::InputEvent::Kind::Wheel) {
      io.AddMouseWheelEvent(0.0f, ev.wheel);
    } else if (ev.kind == EditorState::InputEvent::Kind::Key) {
      // Small named key set for UI navigation.
      ImGuiKey key = ImGuiKey_None;
      switch (ev.key) {
      case 27:
        key = ImGuiKey_Escape;
        break;
      case 13:
        key = ImGuiKey_Enter;
        break;
      case 9:
        key = ImGuiKey_Tab;
        break;
      case 32:
        key = ImGuiKey_Space;
        break;
      case 37:
        key = ImGuiKey_LeftArrow;
        break;
      case 38:
        key = ImGuiKey_UpArrow;
        break;
      case 39:
        key = ImGuiKey_RightArrow;
        break;
      case 40:
        key = ImGuiKey_DownArrow;
        break;
      default:
        break;
      }
      if (key != ImGuiKey_None)
        io.AddKeyEvent(key, ev.down);
    }
    state.mcp_input_queue.pop_front();
    // One non-wait event per frame keeps ImGui click/hover sequencing stable.
    break;
  }
}

void draw_mcp_cursor_overlay(const EditorState &state) {
  if (!state.mcp_draw_cursor || state.mcp_cursor_x < 0.0f ||
      state.mcp_cursor_y < 0.0f)
    return;
  ImDrawList *draw = ImGui::GetForegroundDrawList();
  const ImVec2 p{state.mcp_cursor_x, state.mcp_cursor_y};
  draw->AddCircleFilled(p, 5.0f, IM_COL32(255, 200, 60, 220), 12);
  draw->AddCircle(p, 8.0f, IM_COL32(20, 16, 8, 255), 12, 2.0f);
  draw->AddLine(ImVec2(p.x - 14.0f, p.y), ImVec2(p.x + 14.0f, p.y),
                IM_COL32(255, 220, 100, 180), 1.5f);
  draw->AddLine(ImVec2(p.x, p.y - 14.0f), ImVec2(p.x, p.y + 14.0f),
                IM_COL32(255, 220, 100, 180), 1.5f);
}

void mark_scene_dirty(EditorState &state) {
  state.scene_dirty = true;
  state.static_render_cache_dirty = true;
  state.hover_screen_bounds_sources_dirty = true;
  state.hover_screen_bounds_dirty = true;
}

void apply_project_sync_response(EditorState &state,
                                 const EditorBridgeResponse &response) {
  state.project_sync_summary = response.summary;
  if (const auto it = response.metadata.find("branch");
      it != response.metadata.end())
    state.project_sync_branch = it->second;
  std::ostringstream detail;
  if (const auto it = response.metadata.find("dirtyPaths");
      it != response.metadata.end() && !it->second.empty())
    detail << "Dirty:\n" << it->second << '\n';
  if (const auto it = response.metadata.find("conflictedPaths");
      it != response.metadata.end() && !it->second.empty())
    detail << "Conflicts:\n" << it->second << '\n';
  if (const auto it = response.metadata.find("changedPaths");
      it != response.metadata.end() && !it->second.empty())
    detail << "Changed:\n" << it->second << '\n';
  if (!response.diagnostics.empty())
    detail << response.diagnostics.front().message;
  state.project_sync_detail = detail.str();
  state.status = response.summary;

  const auto meta_flag = [&](const char *key) {
    const auto it = response.metadata.find(key);
    return it != response.metadata.end() && it->second == "true";
  };
  state.project_sync_offer_wf_reload = false;
  state.project_sync_block_scene_reload = false;
  if (response.exit_code == ExitCode::Success &&
      meta_flag("requiresWorldForgeReload")) {
    if (state.scene_dirty || state.terrain_edits_dirty ||
        state.terrain_paint_dirty || state.foliage_density_dirty) {
      if (meta_flag("changedScene")) {
        state.project_sync_block_scene_reload = true;
        state.project_sync_summary += " — save or discard Scene/Sculpt before "
                                      "applying pulled scene changes";
      }
    }
    if (state.world_forge_editor.dirty) {
      state.project_sync_summary +=
          " — World Forge has unsaved edits; Save or discard before Reload";
    } else {
      state.project_sync_offer_wf_reload = true;
    }
  }
}

void run_project_sync_action(EditorState &state, const std::string &action) {
  nlohmann::json params = {{"action", action}};
  if (action == "commit") {
    params["message"] = state.project_sync_commit_message;
  }
  apply_project_sync_response(
      state, apply_project_git_operation(state.project_root, params));
}

void draw_project_sync_panel(EditorState &state) {
  ImGui::Separator();
  ImGui::TextUnformatted("Project Sync (git)");
  if (!state.project_sync_branch.empty())
    ImGui::Text("Branch: %s", state.project_sync_branch.c_str());
  else
    ImGui::TextDisabled("Branch: (unknown — Status to refresh)");
  ImGui::TextWrapped("%s", state.project_sync_summary.c_str());
  if (ImGui::Button("Status##ProjectSync"))
    run_project_sync_action(state, "status");
  ImGui::SameLine();
  if (ImGui::Button("Fetch##ProjectSync"))
    run_project_sync_action(state, "fetch");
  ImGui::SameLine();
  if (ImGui::Button("Pull##ProjectSync"))
    run_project_sync_action(state, "pull");
  ImGui::SameLine();
  if (ImGui::Button("Push##ProjectSync"))
    run_project_sync_action(state, "push");
  ImGui::InputTextWithHint("##ProjectSyncCommitMessage", "Commit message",
                           state.project_sync_commit_message,
                           sizeof(state.project_sync_commit_message));
  ImGui::SameLine();
  if (ImGui::Button("Commit##ProjectSync"))
    run_project_sync_action(state, "commit");
  if (state.project_sync_offer_wf_reload) {
    ImGui::Spacing();
    ImGui::TextColored(ImVec4(0.55f, 0.85f, 0.55f, 1.0f),
                       "Pulled World Forge changes are on disk.");
    if (ImGui::Button("Reload World Forge##ProjectSyncReload")) {
      if (state.world_forge_editor.dirty) {
        state.status = "Save or discard World Forge edits before reload";
      } else {
        const auto reloaded =
            state.world_forge_editor.reload(state.project_root);
        if (!reloaded) {
          state.status =
              "World Forge reload failed: " + reloaded.error().message;
          state.project_sync_detail = reloaded.error().message;
        } else {
          state.status = "World Forge reloaded after pull";
          state.project_sync_offer_wf_reload = false;
          state.project_sync_summary = "World Forge reloaded after pull";
        }
      }
    }
  }
  if (state.project_sync_block_scene_reload) {
    ImGui::TextColored(
        ImVec4(0.95f, 0.75f, 0.35f, 1.0f),
        "Pulled scene/terrain files while the editor has unsaved Scene/Sculpt "
        "work. Save or discard, then restart or reload carefully.");
  }
  if (!state.project_sync_detail.empty()) {
    ImGui::BeginChild("ProjectSyncDetail", ImVec2(0.0f, 96.0f), true);
    ImGui::TextUnformatted(state.project_sync_detail.c_str());
    ImGui::EndChild();
  }
  ImGui::TextDisabled(
      "Uses system git + OS credentials. Save World Forge before Commit.");
}

// --- Diagnostics → Coordination (TICKET-0228): agent build lease + backlog +
// Act 0 MVP claims ---

void refresh_build_coordination(EditorState &state, bool force) {
  if (state.project_root.empty())
    return;
  const double now = ImGui::GetTime();
  if (!force && now - state.coordination_last_refresh < 2.0)
    return;
  state.coordination_last_refresh = now;
  const auto response = apply_build_coordination_operation(
      state.project_root, nlohmann::json{{"action", "status"}});
  state.coordination_meta = response.metadata;
  state.coordination_summary = response.summary;
  if (force || now - state.coordination_backlog_refreshed >= 10.0) {
    state.coordination_backlog_refreshed = now;
    const auto root = build_coordination_root(state.project_root);
    auto backlog =
        load_planning_backlog(root / "context" / "planning" / "epics.md");
    if (backlog) {
      state.coordination_backlog = std::move(backlog.value());
      state.coordination_backlog_error.clear();
    } else {
      state.coordination_backlog_error = backlog.error().message;
    }
  }
}

void run_build_coordination_clear(EditorState &state, bool force) {
  nlohmann::json params{{"action", "clear-stale"}, {"agentId", "editor-owner"}};
  if (force)
    params["force"] = true;
  const auto response =
      apply_build_coordination_operation(state.project_root, params);
  state.status = response.summary;
  refresh_build_coordination(state, true);
}

void draw_build_coordination_tab(EditorState &state) {
  refresh_build_coordination(state, false);
  const auto meta = [&](const char *key) -> std::string {
    const auto it = state.coordination_meta.find(key);
    return it != state.coordination_meta.end() ? it->second : std::string{};
  };
  const auto parse_json_array = [](const std::string &text) {
    auto doc =
        nlohmann::json::parse(text.empty() ? "[]" : text, nullptr, false);
    if (doc.is_discarded() || !doc.is_array())
      doc = nlohmann::json::array();
    return doc;
  };
  const std::int64_t now_epoch_ms =
      std::chrono::duration_cast<std::chrono::milliseconds>(
          std::chrono::system_clock::now().time_since_epoch())
          .count();

  const ImVec4 gold(0.84f, 0.73f, 0.47f, 1.0f);
  const ImVec4 green(0.55f, 0.85f, 0.55f, 1.0f);
  const ImVec4 amber(0.95f, 0.75f, 0.35f, 1.0f);
  const ImVec4 red(1.0f, 0.4f, 0.2f, 1.0f);

  ImGui::TextColored(gold, "Rebuild lease");
  ImGui::SameLine();
  if (ImGui::SmallButton("Refresh##Coordination"))
    refresh_build_coordination(state, true);
  const std::string lease_agent = meta("leaseAgentId");
  if (!lease_agent.empty()) {
    const std::string ticket = meta("leaseTicketId");
    ImGui::TextColored(amber, "HELD by %s (%s)", lease_agent.c_str(),
                       ticket.c_str());
    const std::string summary = meta("leaseSummary");
    if (!summary.empty())
      ImGui::TextWrapped("Work: %s", summary.c_str());
    std::int64_t expires_at = 0;
    try {
      expires_at = std::stoll(meta("leaseExpiresAtMs"));
    } catch (...) {
    }
    if (expires_at > 0) {
      const auto remaining =
          std::max<std::int64_t>(0, expires_at - now_epoch_ms);
      ImGui::Text("Expires in %lld:%02lld",
                  static_cast<long long>(remaining / 60000),
                  static_cast<long long>((remaining / 1000) % 60));
    }
    if (meta("leasePid") != "0") {
      ImGui::Text("Owner pid %s (%s)", meta("leasePid").c_str(),
                  meta("leasePidAlive") == "true" ? "alive" : "not running");
      if (meta("leasePidAlive") == "false")
        ImGui::TextColored(
            red,
            "Owner process is gone — Clear stale will reclaim this lease.");
    } else {
      ImGui::TextDisabled(
          "Not process-bound — reclaimed on expiry (or Force clear).");
    }
  } else {
    ImGui::TextColored(green, "IDLE — the rebuild slot is free.");
  }
  if (ImGui::Button("Clear stale##Coordination"))
    run_build_coordination_clear(state, false);
  ImGui::SameLine();
  if (ImGui::Button("Force clear...##Coordination"))
    ImGui::OpenPopup("ForceClearLease");
  if (ImGui::BeginPopupModal("ForceClearLease", nullptr,
                             ImGuiWindowFlags_AlwaysAutoResize)) {
    ImGui::TextWrapped("Force-clear the ACTIVE build lease? Only do this when "
                       "the holding agent is stuck; its rebuild may "
                       "still be running.");
    if (ImGui::Button("Force clear")) {
      run_build_coordination_clear(state, true);
      ImGui::CloseCurrentPopup();
    }
    ImGui::SameLine();
    if (ImGui::Button("Cancel"))
      ImGui::CloseCurrentPopup();
    ImGui::EndPopup();
  }
  ImGui::TextDisabled("Agents: engine_build_coordination acquire/wait before "
                      "MSBuild; release after restart. Direct manual "
                      "builds bypass this lease.");

  ImGui::Separator();
  ImGui::TextColored(gold, "Waiting queue");
  const auto queue = parse_json_array(meta("queueJson"));
  if (queue.empty()) {
    ImGui::TextDisabled("No agents waiting.");
  } else if (ImGui::BeginTable("CoordinationQueue", 3,
                               ImGuiTableFlags_RowBg |
                                   ImGuiTableFlags_BordersInnerH |
                                   ImGuiTableFlags_SizingStretchProp)) {
    ImGui::TableSetupColumn("Agent");
    ImGui::TableSetupColumn("Ticket");
    ImGui::TableSetupColumn("Work");
    ImGui::TableHeadersRow();
    for (const auto &entry : queue) {
      ImGui::TableNextRow();
      ImGui::TableNextColumn();
      ImGui::TextUnformatted(entry.value("agentId", std::string{}).c_str());
      ImGui::TableNextColumn();
      ImGui::TextUnformatted(entry.value("ticketId", std::string{}).c_str());
      ImGui::TableNextColumn();
      ImGui::TextWrapped("%s", entry.value("summary", std::string{}).c_str());
    }
    ImGui::EndTable();
  }

  const auto events = parse_json_array(meta("eventsJson"));
  if (!events.empty()) {
    ImGui::Separator();
    ImGui::TextColored(gold, "Recent events");
    for (auto it = events.rbegin(); it != events.rend(); ++it) {
      ImGui::BulletText("%s — %s", it->value("kind", std::string{}).c_str(),
                        it->value("detail", std::string{}).c_str());
    }
  }

  ImGui::Separator();
  ImGui::TextColored(gold, "Backlog (epics.md, read-only)");
  if (!state.coordination_backlog_error.empty()) {
    ImGui::TextColored(red, "%s", state.coordination_backlog_error.c_str());
  } else if (state.coordination_backlog.tickets.empty()) {
    ImGui::TextDisabled("Backlog not loaded yet.");
  } else {
    const auto counts = state.coordination_backlog.status_counts();
    std::string totals;
    for (const char *status : {"active", "ready", "needs-approval", "proposed",
                               "done", "deferred"}) {
      const auto it = counts.find(status);
      if (it == counts.end())
        continue;
      if (!totals.empty())
        totals += "  ·  ";
      totals += std::string(status) + " " + std::to_string(it->second);
    }
    ImGui::TextWrapped("%zu tickets: %s",
                       state.coordination_backlog.tickets.size(),
                       totals.c_str());
    std::string active_line;
    for (const auto &ticket : state.coordination_backlog.tickets) {
      if (ticket.status != "active")
        continue;
      if (!active_line.empty())
        active_line += ", ";
      active_line += ticket.id;
    }
    if (!active_line.empty())
      ImGui::TextWrapped("Active now: %s", active_line.c_str());
  }

  ImGui::Separator();
  ImGui::TextColored(gold, "Act 0 MVP readiness");
  auto &wf = state.world_forge_editor;
  if (!wf.loaded && !state.project_root.empty()) {
    if (const auto loaded = wf.reload(state.project_root); !loaded)
      ImGui::TextColored(red, "World Forge load failed: %s",
                         loaded.error().message.c_str());
  }
  const auto &readiness = wf.mvp_readiness;
  if (readiness.categories.empty()) {
    ImGui::TextDisabled("No MVP readiness checklist loaded.");
    return;
  }
  const int total_items = readiness.count_items();
  const int done_items = readiness.count_done();
  char progress_label[64];
  std::snprintf(progress_label, sizeof(progress_label), "%d / %d done",
                done_items, total_items);
  ImGui::ProgressBar(readiness.done_fraction(), ImVec2(-1.0f, 0.0f),
                     progress_label);

  const std::string lease_ticket = meta("leaseTicketId");
  std::map<std::string, std::string> queued_agents_by_ticket;
  for (const auto &entry : queue)
    queued_agents_by_ticket[entry.value("ticketId", std::string{})] =
        entry.value("agentId", std::string{});

  const float table_height = std::min(
      320.0f, std::max(120.0f, ImGui::GetContentRegionAvail().y - 8.0f));
  if (ImGui::BeginChild("CoordinationMvp", ImVec2(0.0f, table_height), true)) {
    if (ImGui::BeginTable("CoordinationMvpTable", 5,
                          ImGuiTableFlags_RowBg |
                              ImGuiTableFlags_BordersInnerH |
                              ImGuiTableFlags_SizingStretchProp)) {
      ImGui::TableSetupColumn("Item", ImGuiTableColumnFlags_WidthStretch,
                              0.42f);
      ImGui::TableSetupColumn("Lens", ImGuiTableColumnFlags_WidthStretch,
                              0.13f);
      ImGui::TableSetupColumn("Status", ImGuiTableColumnFlags_WidthStretch,
                              0.10f);
      ImGui::TableSetupColumn("Ticket", ImGuiTableColumnFlags_WidthStretch,
                              0.17f);
      ImGui::TableSetupColumn("Who", ImGuiTableColumnFlags_WidthStretch, 0.18f);
      ImGui::TableHeadersRow();
      for (const auto &category : readiness.categories) {
        for (const auto &item : category.items) {
          ImGui::TableNextRow();
          ImGui::TableNextColumn();
          ImGui::TextWrapped("%s", item.title.c_str());
          ImGui::TableNextColumn();
          ImGui::TextUnformatted(
              world_forge_mvp_workstream_label(item.workstream));
          ImGui::TableNextColumn();
          const ImVec4 status_color =
              item.status == WorldForgeMvpItemStatus::Done
                  ? green
                  : item.status == WorldForgeMvpItemStatus::Wip
                        ? amber
                        : item.status == WorldForgeMvpItemStatus::Blocked
                              ? red
                              : ImVec4(0.7f, 0.7f, 0.7f, 1.0f);
          ImGui::TextColored(status_color, "%s", to_string(item.status));
          ImGui::TableNextColumn();
          if (item.refs.ticket_id.empty()) {
            ImGui::TextDisabled("-");
          } else {
            const auto *ticket =
                state.coordination_backlog.find(item.refs.ticket_id);
            if (ticket) {
              ImGui::Text("%s (%s)", item.refs.ticket_id.c_str(),
                          ticket->status.c_str());
            } else {
              ImGui::TextUnformatted(item.refs.ticket_id.c_str());
            }
          }
          ImGui::TableNextColumn();
          if (!item.refs.ticket_id.empty() &&
              item.refs.ticket_id == lease_ticket) {
            ImGui::TextColored(amber, "building now (%s)", lease_agent.c_str());
          } else if (const auto queued_it =
                         queued_agents_by_ticket.find(item.refs.ticket_id);
                     !item.refs.ticket_id.empty() &&
                     queued_it != queued_agents_by_ticket.end()) {
            ImGui::TextColored(gold, "queued (%s)", queued_it->second.c_str());
          } else {
            ImGui::TextDisabled("-");
          }
        }
      }
      ImGui::EndTable();
    }
  }
  ImGui::EndChild();
}

void open_script_binding(EditorState &state, const std::string &kind,
                         const std::string &binding_id) {
  const auto relative =
      resolve_script_binding_path(state.project_root, kind, binding_id);
  if (!relative) {
    state.status = relative.error().message;
    Logger::instance().write(relative.error());
    return;
  }
  const std::string &relative_path = relative.value();
  const auto absolute = (state.project_root / relative_path).lexically_normal();
  if (!std::filesystem::exists(absolute)) {
    state.status =
        "Script file missing: " + normalize_asset_path(relative_path);
    Logger::instance().write(
        EngineError{"SCRIPT-FILE-MISSING",
                    Severity::Error,
                    ErrorCategory::Io,
                    "editor",
                    state.status,
                    ENGINE_SOURCE_CONTEXT,
                    {},
                    "Create the Lua file or fix the bindings path.",
                    make_correlation_id()});
    return;
  }
  const HINSTANCE opened =
      ShellExecuteW(nullptr, L"open", absolute.wstring().c_str(), nullptr,
                    nullptr, SW_SHOWNORMAL);
  if (reinterpret_cast<INT_PTR>(opened) <= 32) {
    state.status =
        "Failed to open script: " + normalize_asset_path(relative_path);
    return;
  }
  state.status = "Opened " + normalize_asset_path(relative_path);
}

bool draw_collider_property_fields(PrefabCollisionVolume &volume) {
  bool commit = false;
  int shape_index = volume.shape == PrefabCollisionShape::Box
                        ? 0
                        : volume.shape == PrefabCollisionShape::Sphere ? 1 : 2;
  if (ImGui::Combo("Shape", &shape_index, "box\0sphere\0capsule\0")) {
    volume.shape = shape_index == 0
                       ? PrefabCollisionShape::Box
                       : shape_index == 1 ? PrefabCollisionShape::Sphere
                                          : PrefabCollisionShape::Capsule;
    commit = true;
  }
  if (volume.shape == PrefabCollisionShape::Box) {
    float half_extent[3] = {volume.half_extent.x, volume.half_extent.y,
                            volume.half_extent.z};
    ImGui::InputFloat3("Half Extent", half_extent);
    volume.half_extent = {half_extent[0], half_extent[1], half_extent[2]};
    if (ImGui::IsItemDeactivatedAfterEdit())
      commit = true;
  } else if (volume.shape == PrefabCollisionShape::Capsule) {
    ImGui::InputFloat("Radius", &volume.radius);
    if (ImGui::IsItemDeactivatedAfterEdit())
      commit = true;
    ImGui::InputFloat("Half Height", &volume.capsule_half_height);
    if (ImGui::IsItemDeactivatedAfterEdit())
      commit = true;
  } else {
    ImGui::InputFloat("Radius", &volume.radius);
    if (ImGui::IsItemDeactivatedAfterEdit())
      commit = true;
  }
  float offset[3] = {volume.transform.position[0], volume.transform.position[1],
                     volume.transform.position[2]};
  ImGui::InputFloat3("Offset", offset);
  volume.transform.position = {offset[0], offset[1], offset[2]};
  if (ImGui::IsItemDeactivatedAfterEdit())
    commit = true;
  if (ImGui::Checkbox("Trigger", &volume.trigger))
    commit = true;
  return commit;
}

bool draw_script_binding_property_fields(ScriptBindingComponentData &script,
                                         char *kind_buf,
                                         std::size_t kind_buf_size,
                                         char *binding_buf,
                                         std::size_t binding_buf_size) {
  bool commit = false;
  int kind_index = 0;
  const std::string kind_key = script.kind;
  std::string kind_lower = kind_key;
  std::transform(kind_lower.begin(), kind_lower.end(), kind_lower.begin(),
                 [](unsigned char character) {
                   return static_cast<char>(std::tolower(character));
                 });
  if (kind_lower == "combathit")
    kind_index = 1;
  else if (kind_lower == "combathurt")
    kind_index = 2;
  else if (kind_lower == "handler")
    kind_index = 3;
  if (ImGui::Combo("Kind", &kind_index,
                   "interaction\0combatHit\0combatHurt\0handler\0")) {
    static constexpr const char *k_kinds[] = {"interaction", "combatHit",
                                              "combatHurt", "handler"};
    script.kind = k_kinds[kind_index];
    std::snprintf(kind_buf, kind_buf_size, "%s", script.kind.c_str());
    commit = true;
  }
  ImGui::InputText("Binding Id", binding_buf, binding_buf_size);
  if (ImGui::IsItemDeactivatedAfterEdit()) {
    script.binding_id = binding_buf;
    commit = true;
  }
  return commit;
}

void commit_entity_component_edit(EditorState &state,
                                  AuthoredComponentEntry entry) {
  const auto result = state.history.execute(
      state.scene, std::make_unique<SetEntityComponentCommand>(
                       *state.selected, std::move(entry)));
  state.status = result ? "Component updated" : result.error().message;
  if (!result)
    Logger::instance().write(result.error());
  else
    mark_scene_dirty(state);
}

